// The invalidation rules I1–I7 of chapter 06 §6.7.3 (WI-0.092).

#include "cache/invalidate.hpp"

#include <nlohmann/json.hpp>

#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <system_error>

#include "cache/atomic_file.hpp"
#include "cache/fb_verify.hpp"
#include "ovt/cxx/cache/cache.hpp"
#include "ovt/cxx/cache/error.hpp"
#include "ovt/cxx/cache/meta.hpp"
#include "ovt/cxx/log.hpp"
#include "ovt/cxx/model/schema_version.hpp"
#include "ovt_model_generated.h"
#include "ovt_version_full.h"  // OVT_VERSION_FULL, generated by cmake/OvtVersion.cmake

namespace ovt::cache {

namespace fs = std::filesystem;

namespace {

constexpr const char* kModule = "cache";
constexpr std::size_t kMaxJsonBytes = 64U << 20U;
constexpr std::size_t kMaxIndexBytes = 1U << 30U;

}  // namespace

namespace {

// I2 on <dir>/meta.json: a missing or unreadable file fails like a malformed one.
InvalidationReason load_meta(const fs::path& dir, Meta& meta) {
  try {
    return check_cache_format(read_file(dir / "meta.json", kMaxJsonBytes), &meta);
  } catch (const CacheError& e) {
    OVT_LOG(log::Level::Info, kModule, "{}", e.what());
    return InvalidationReason::CacheFormat;
  }
}

// I4 on <dir>/index.fb when it exists (an entry without an index is valid).
InvalidationReason load_index_reason(const fs::path& dir, const Meta& meta, std::optional<fb::Codec> codec) {
  const fs::path path = dir / "index.fb";
  std::error_code ec;
  if (!fs::is_regular_file(path, ec)) {
    return InvalidationReason::None;
  }
  try {
    return check_index(read_file(path, kMaxIndexBytes), meta, codec);
  } catch (const CacheError& e) {
    OVT_LOG(log::Level::Info, kModule, "{}", e.what());
    return InvalidationReason::Index;
  }
}

}  // namespace

std::string_view to_string(InvalidationReason reason) noexcept {
  switch (reason) {
    case InvalidationReason::None:
      return "none";
    case InvalidationReason::ForeignSourceHash:
      return "I1 source hash";
    case InvalidationReason::CacheFormat:
      return "I2 cache format";
    case InvalidationReason::SchemaMajor:
      return "I3 schema major";
    case InvalidationReason::Index:
      return "I4 index";
    case InvalidationReason::Frame:
      return "I5 frame";
    case InvalidationReason::Plane:
      return "I6 plane";
    case InvalidationReason::OvtVersion:
      return "I7 ovt version";
  }
  return "unknown";
}

InvalidationReason check_cache_format(std::span<const std::uint8_t> meta_json, Meta* out) {
  const nlohmann::json doc = nlohmann::json::parse(meta_json.begin(), meta_json.end(), nullptr, false, false);
  if (!doc.is_object()) {
    return InvalidationReason::CacheFormat;
  }
  const auto format = doc.find("cache_format");
  if (format == doc.end() || !format->is_number_unsigned() || format->get<std::uint64_t>() != kCacheFormat) {
    return InvalidationReason::CacheFormat;
  }
  try {
    Meta meta = parse_meta(meta_json);
    if (out != nullptr) {
      *out = std::move(meta);
    }
  } catch (const CacheError& e) {
    OVT_LOG(log::Level::Info, kModule, "{}", e.what());
    return InvalidationReason::CacheFormat;
  }
  return InvalidationReason::None;
}

InvalidationReason check_source_hash(const Meta& meta, std::string_view dir_name) noexcept {
  return meta.source_hash == dir_name ? InvalidationReason::None : InvalidationReason::ForeignSourceHash;
}

InvalidationReason check_schema_majors(const Meta& meta) noexcept {
  const bool ok = meta.ovt_model.major == model::kModelSchemaMajor &&
                  meta.ovt_container.major == model::kContainerSchemaMajor &&
                  meta.ovt_metrics.major == model::kMetricsSchemaMajor;
  return ok ? InvalidationReason::None : InvalidationReason::SchemaMajor;
}

InvalidationReason check_index(std::span<const std::uint8_t> index_fb, const Meta& meta,
                               std::optional<fb::Codec> codec) {
  const auto* index = verify_size_prefixed<fb::StreamIndex>(index_fb, "OVTI");
  if (index == nullptr || index->schema_version() != model::kModelSchemaMajor ||
      meta.codec != fb::EnumNameCodec(index->codec()) || (codec && index->codec() != *codec)) {
    return InvalidationReason::Index;
  }
  return InvalidationReason::None;
}

InvalidationReason check_frame(std::span<const std::uint8_t> frame_fb, std::uint32_t decode_index,
                               const std::optional<SelectedPlugin>& plugin) {
  const auto* fa = verify_size_prefixed<fb::FrameAnalysis>(frame_fb, "OVTA");
  if (fa == nullptr || fa->frame() == nullptr || fa->frame()->id() == nullptr ||
      fa->frame()->id()->decode_index() != static_cast<std::int32_t>(decode_index)) {
    return InvalidationReason::Frame;
  }
  if (plugin) {
    const std::string_view id = fa->plugin_id() != nullptr ? fa->plugin_id()->string_view() : std::string_view();
    const std::string_view version =
        fa->plugin_version() != nullptr ? fa->plugin_version()->string_view() : std::string_view();
    if (id != plugin->plugin_id || version != plugin->plugin_version) {
      return InvalidationReason::Frame;
    }
  }
  return InvalidationReason::None;
}

InvalidationReason check_plane(const fb::FrameAnalysis& frame, fb::PlaneStage stage, std::uint8_t plane,
                               std::size_t plane_bytes) {
  if (frame.planes() != nullptr) {
    for (const fb::PlaneRef* ref : *frame.planes()) {
      if (ref->stage() == stage && ref->plane() == plane) {
        const std::uint64_t expected = static_cast<std::uint64_t>(ref->width()) * ref->sample_bytes() * ref->height();
        return expected == plane_bytes ? InvalidationReason::None : InvalidationReason::Plane;
      }
    }
  }
  return InvalidationReason::Plane;
}

InvalidationReason check_ovt_version(const Meta& meta) noexcept {
  return meta.ovt_version == OVT_VERSION_FULL ? InvalidationReason::None : InvalidationReason::OvtVersion;
}

InvalidationReason check_entry_dir(const fs::path& dir, std::string_view hex, std::optional<fb::Codec> codec) {
  const auto reject = [&](InvalidationReason reason, std::string_view detail) {
    OVT_LOG(log::Level::Info, kModule, "entry {} fails {}: {}", hex, to_string(reason), detail);
    return reason;
  };
  Meta meta;
  if (const InvalidationReason r = load_meta(dir, meta); r != InvalidationReason::None) {
    return reject(r, "meta.json is missing, malformed or of another cache_format");
  }
  if (check_source_hash(meta, hex) != InvalidationReason::None) {
    return reject(InvalidationReason::ForeignSourceHash, "meta.source_hash names another source");
  }
  if (check_schema_majors(meta) != InvalidationReason::None) {
    return reject(InvalidationReason::SchemaMajor, "written with another schema major");
  }
  if (load_index_reason(dir, meta, codec) != InvalidationReason::None) {
    return reject(InvalidationReason::Index, "index.fb does not verify or names another codec");
  }
  if (check_ovt_version(meta) != InvalidationReason::None) {
    OVT_LOG(log::Level::Info, kModule, "entry {} was written by ovt {}, running {} (I7: kept)", hex, meta.ovt_version,
            OVT_VERSION_FULL);
  }
  return InvalidationReason::None;
}

}  // namespace ovt::cache
